// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Login
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoke the refresh token family and clear the cookie
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Refresh Rotate the refresh cookie and issue a new access token
	// (POST /auth/refresh)
	Refresh(ctx context.Context, request RefreshRequestObject) (RefreshResponseObject, error)
	// Setup Create the first platform admin using the one-time setup token
	// (POST /auth/setup)
	Setup(ctx context.Context, request SetupRequestObject) (SetupResponseObject, error)
	// GetHealth Public node status
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// ListIncidents List incidents
	// (GET /incidents)
	ListIncidents(ctx context.Context, request ListIncidentsRequestObject) (ListIncidentsResponseObject, error)
	// GetIncident Get incident
	// (GET /incidents/{incidentId})
	GetIncident(ctx context.Context, request GetIncidentRequestObject) (GetIncidentResponseObject, error)
	// ListMaintenanceWindows List maintenance windows
	// (GET /maintenance)
	ListMaintenanceWindows(ctx context.Context, request ListMaintenanceWindowsRequestObject) (ListMaintenanceWindowsResponseObject, error)
	// CreateMaintenanceWindow Create maintenance window
	// (POST /maintenance)
	CreateMaintenanceWindow(ctx context.Context, request CreateMaintenanceWindowRequestObject) (CreateMaintenanceWindowResponseObject, error)
	// DeleteMaintenanceWindow Delete maintenance window
	// (DELETE /maintenance/{maintenanceId})
	DeleteMaintenanceWindow(ctx context.Context, request DeleteMaintenanceWindowRequestObject) (DeleteMaintenanceWindowResponseObject, error)
	// GetMaintenanceWindow Get maintenance window
	// (GET /maintenance/{maintenanceId})
	GetMaintenanceWindow(ctx context.Context, request GetMaintenanceWindowRequestObject) (GetMaintenanceWindowResponseObject, error)
	// UpdateMaintenanceWindow Update maintenance window
	// (PUT /maintenance/{maintenanceId})
	UpdateMaintenanceWindow(ctx context.Context, request UpdateMaintenanceWindowRequestObject) (UpdateMaintenanceWindowResponseObject, error)
	// GetMe Get the current user
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ChangeMyPassword Change my password
	// (PUT /me/password)
	ChangeMyPassword(ctx context.Context, request ChangeMyPasswordRequestObject) (ChangeMyPasswordResponseObject, error)
	// ListMonitorTypes Available checker plugins with their JSON schema
	// (GET /monitor-types)
	ListMonitorTypes(ctx context.Context, request ListMonitorTypesRequestObject) (ListMonitorTypesResponseObject, error)
	// ListMonitors List monitors
	// (GET /monitors)
	ListMonitors(ctx context.Context, request ListMonitorsRequestObject) (ListMonitorsResponseObject, error)
	// CreateMonitor Create monitor
	// (POST /monitors)
	CreateMonitor(ctx context.Context, request CreateMonitorRequestObject) (CreateMonitorResponseObject, error)
	// DeleteMonitor Delete monitor
	// (DELETE /monitors/{monitorId})
	DeleteMonitor(ctx context.Context, request DeleteMonitorRequestObject) (DeleteMonitorResponseObject, error)
	// GetMonitor Get monitor
	// (GET /monitors/{monitorId})
	GetMonitor(ctx context.Context, request GetMonitorRequestObject) (GetMonitorResponseObject, error)
	// UpdateMonitor Update monitor
	// (PUT /monitors/{monitorId})
	UpdateMonitor(ctx context.Context, request UpdateMonitorRequestObject) (UpdateMonitorResponseObject, error)
	// CloneMonitor Clone monitor
	// (POST /monitors/{monitorId}/clone)
	CloneMonitor(ctx context.Context, request CloneMonitorRequestObject) (CloneMonitorResponseObject, error)
	// ListHeartbeats List heartbeats
	// (GET /monitors/{monitorId}/heartbeats)
	ListHeartbeats(ctx context.Context, request ListHeartbeatsRequestObject) (ListHeartbeatsResponseObject, error)
	// PauseMonitor Pause monitor
	// (POST /monitors/{monitorId}/pause)
	PauseMonitor(ctx context.Context, request PauseMonitorRequestObject) (PauseMonitorResponseObject, error)
	// ResumeMonitor Resume monitor
	// (POST /monitors/{monitorId}/resume)
	ResumeMonitor(ctx context.Context, request ResumeMonitorRequestObject) (ResumeMonitorResponseObject, error)
	// TestMonitor Run the check once now without storing the result
	// (POST /monitors/{monitorId}/test)
	TestMonitor(ctx context.Context, request TestMonitorRequestObject) (TestMonitorResponseObject, error)
	// GetUptime Get uptime
	// (GET /monitors/{monitorId}/uptime)
	GetUptime(ctx context.Context, request GetUptimeRequestObject) (GetUptimeResponseObject, error)
	// ListNotificationChannels List notification channels
	// (GET /notifications)
	ListNotificationChannels(ctx context.Context, request ListNotificationChannelsRequestObject) (ListNotificationChannelsResponseObject, error)
	// CreateNotificationChannel Create notification channel
	// (POST /notifications)
	CreateNotificationChannel(ctx context.Context, request CreateNotificationChannelRequestObject) (CreateNotificationChannelResponseObject, error)
	// DeleteNotificationChannel Delete notification channel
	// (DELETE /notifications/{channelId})
	DeleteNotificationChannel(ctx context.Context, request DeleteNotificationChannelRequestObject) (DeleteNotificationChannelResponseObject, error)
	// GetNotificationChannel Get notification channel
	// (GET /notifications/{channelId})
	GetNotificationChannel(ctx context.Context, request GetNotificationChannelRequestObject) (GetNotificationChannelResponseObject, error)
	// UpdateNotificationChannel Update notification channel
	// (PUT /notifications/{channelId})
	UpdateNotificationChannel(ctx context.Context, request UpdateNotificationChannelRequestObject) (UpdateNotificationChannelResponseObject, error)
	// TestNotificationChannel Send a test message synchronously
	// (POST /notifications/{channelId}/test)
	TestNotificationChannel(ctx context.Context, request TestNotificationChannelRequestObject) (TestNotificationChannelResponseObject, error)
	// CreateStreamTicket One-time ticket (30 s) for opening the WebSocket `/api/v1/stream?ticket=…`
	// (POST /stream/ticket)
	CreateStreamTicket(ctx context.Context, request CreateStreamTicketRequestObject) (CreateStreamTicketResponseObject, error)
	// ListUsers List users
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// CreateUser Create user
	// (POST /users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
	// DeleteUser Delete user
	// (DELETE /users/{userId})
	DeleteUser(ctx context.Context, request DeleteUserRequestObject) (DeleteUserResponseObject, error)
	// UpdateUser Update user
	// (PUT /users/{userId})
	UpdateUser(ctx context.Context, request UpdateUserRequestObject) (UpdateUserResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

